INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('c48bcace-6ca6-5688-8f2a-119c8b36bc87', 'text_image', 'Ons atelier', null, '{"text": "Maison Lune maakt kleding die je jaren draagt: natuurlijke stoffen, rustige kleuren en pasvormen die kloppen. Elk stuk komt uit een klein atelier in Portugal of Italië.", "image_url": "", "image_position": "right", "button_text": "Bekijk alles", "button_link": "/producten"}'::jsonb, '{}'::jsonb, 3, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('c48bcace-6ca6-5688-8f2a-119c8b36bc87', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Hoe vallen de maten?", "answer": "Normaal. Twijfel je tussen twee maten, kies dan de grootste: onze stoffen krimpen niet."}, {"question": "Kan ik ruilen?", "answer": "Ja, binnen 30 dagen gratis, zolang het label er nog aan hangt."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets verzonden of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);